import { copy } from '@dreadnought/core';
async function onCopy(text: string) {
  try { await copy(text); }
  catch (error) { console.error('Не удалось скопировать', error); }
}

import { download } from '@dreadnought/core';
function onExport() {
  download(new Blob(['name,value\nExample,1'], { type: 'text/csv;charset=utf-8' }), 'report.csv');
}

import { pickFiles } from '@dreadnought/core';
async function onAttach() {
  try {
    const files = await pickFiles({ accept: 'image/*', multiple: true });
    if (files.length) console.log(files);
  } catch (error) { console.error('Не удалось выбрать файлы', error); }
}

import { readClipboard } from '@dreadnought/core';
async function onPaste(setValue: (text: string) => void) {
  try { setValue(await readClipboard()); }
  catch (error) { console.error('Не удалось прочитать буфер', error); }
}
